SELECT g.id, g.name, g.category_id, c.name AS categoryName, g.price, g.image, g.description, g.status, g.origin, g.shelf_life, g.storage_zone, g.update_time FROM goods g LEFT JOIN goods_category c ON c.id = g.category_id
AND g.name LIKE CONCAT('%', #{name}, '%')
AND g.category_id = #{categoryId}
AND g.status = #{status}
ORDER BY g.update_time DESC

